#[derive(Debug)]
struct ProjectionSemanticRefusal(String);

impl std::fmt::Display for ProjectionSemanticRefusal {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for ProjectionSemanticRefusal {}

fn projection_semantic_refusal(kind: io::ErrorKind, message: impl Into<String>) -> io::Error {
    io::Error::new(kind, ProjectionSemanticRefusal(message.into()))
}

pub(crate) fn is_projection_semantic_refusal(error: &io::Error) -> bool {
    error
        .get_ref()
        .is_some_and(|source| source.is::<ProjectionSemanticRefusal>())
}

/// Name the filesystem primitive and the graph location behind a raw platform
/// errno on the projection leg.
///
/// The device is the only oracle for Android's shared-storage semantics and one
/// CI round trip costs ~20 minutes, so a receipt that says only
/// `Invalid argument (os error 22)` cannot be acted on. `ErrorKind` is
/// preserved, because callers above classify on it (`NotFound`/`AlreadyExists`
/// are guarded-conflict signals) and the platform durability policy matches on
/// it too. A semantic refusal is returned untouched so its marker type survives.
fn projection_platform_error(operation: &str, location: &str, error: io::Error) -> io::Error {
    if is_projection_semantic_refusal(&error) {
        return error;
    }
    io::Error::new(
        error.kind(),
        format!("{operation} failed at {location}: {error}"),
    )
}

/// Markdown's parser deliberately omits layout trivia such as empty separator
/// lines, but a guarded journal target may retain that trivia through its
/// authenticated projection annotations. This comparison is intentionally
/// stricter than `Document`'s content-only `PartialEq`: it keeps the exact
/// preamble, block order/ancestry, raw block bodies (including `id::` lines),
/// and parser-carried identity metadata equal.
fn guarded_markdown_documents_match(left: &str, right: &str) -> bool {
    fn blocks_match(left: &DocBlock, right: &DocBlock) -> bool {
        left.raw == right.raw
            && left.uuid == right.uuid
            && left.is_org == right.is_org
            && left.children.len() == right.children.len()
            && left
                .children
                .iter()
                .zip(&right.children)
                .all(|(left, right)| blocks_match(left, right))
    }

    let Ok(left) = doc::try_parse_with_source_spans(left) else {
        return false;
    };
    let Ok(right) = doc::try_parse_with_source_spans(right) else {
        return false;
    };
    left.document.pre_block == right.document.pre_block
        && left.document.roots.len() == right.document.roots.len()
        && left
            .document
            .roots
            .iter()
            .zip(&right.document.roots)
            .all(|(left, right)| blocks_match(left, right))
}

/// One lexical/scope validation result shared by exact points and feed events.
///
/// This deliberately has no twin path. `.markdown` is one exact physical
/// spelling, not an instruction to synthesize an `.md` or `.org` neighbor.
#[derive(Clone, Debug)]
struct GraphTextExactPath {
    managed_path: Option<ManagedPath>,
    parent_components: Vec<String>,
    filename: String,
}

struct ProjectionParent {
    chain: Vec<Dir>,
}

impl ProjectionParent {
    fn final_dir(&self) -> &Dir {
        self.chain
            .last()
            .expect("projection parent chain always contains the graph root")
    }
}

enum ProjectionParentCapture {
    Missing,
    Present(ProjectionParent),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum EditorPublicationAuthority {
    /// The Markdown/Org file is the sole durable authority (Direct Files).
    DirectFile,
    /// The file is a rebuildable managed-storage projection whose durable
    /// authority is the accepted journal/manifest.
    ReconstructibleManagedProjection,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum GraphTextPublicationValidation {
    /// Standalone callers have not established graph-wide collision evidence.
    CompleteIndex,
    /// One exact source/destination transition proves portable aliases,
    /// retained parent ownership, the source's single-link identity, and the
    /// destination's absence directly. No document contents are relevant.
    PathLocal,
    /// A surrounding transaction owns graph-text identity authority and has
    /// already completed a bounded no-follow inventory. Publication still
    /// repeats exact target, single-link, portable-path, and no-clobber checks.
    TransactionInventory,
}

fn preflight_editor_publication_chain(
    authority: EditorPublicationAuthority,
    chain: &[Dir],
) -> io::Result<()> {
    match authority {
        EditorPublicationAuthority::DirectFile => preflight_projection_chain(chain),
        EditorPublicationAuthority::ReconstructibleManagedProjection => {
            preflight_reconstructible_projection_chain(chain)
        }
    }
}

fn sync_editor_publication_chain(
    authority: EditorPublicationAuthority,
    chain: &[Dir],
) -> io::Result<()> {
    match authority {
        EditorPublicationAuthority::DirectFile => sync_projection_chain_required(chain),
        EditorPublicationAuthority::ReconstructibleManagedProjection => {
            sync_reconstructible_projection_chain(chain)
        }
    }
}

fn validate_projection_attempt(
    target: &ProjectionTarget,
    attempt: &ProjectionAttemptReservation,
) -> io::Result<()> {
    #[cfg(test)]
    let filename = if projection_case_alias_is_armed(&target.relative_path) {
        target
            .relative_path
            .rsplit('/')
            .next()
            .expect("validated projection path has a filename")
    } else {
        &target.filename
    };
    #[cfg(not(test))]
    let filename = &target.filename;
    let expected = format!(
        ".{}.{}.projection.recovery",
        filename,
        attempt.attempt_id().simple()
    );
    if attempt.target_path().as_str() != target.relative_path
        || attempt.recovery_filename() != expected
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "projection attempt is not bound to the target capability",
        ));
    }
    Ok(())
}

/// Parse a page file's bytes into a [`Document`] using the parser for its
/// format (org headlines vs markdown bullets), chosen by the path's extension.
fn parse_doc(path: &Path, content: &str) -> Document {
    match Format::from_path(path) {
        Format::Md => doc::parse(content),
        Format::Org => crate::org::parse_org(content),
    }
}

fn bind_guarded_projection_identities(
    document: &mut Document,
    identities: &[StructuralLayoutIdentity],
) -> io::Result<()> {
    fn bind_blocks(
        blocks: &mut [DocBlock],
        locator: &mut Vec<u32>,
        identities: &[StructuralLayoutIdentity],
        index: &mut usize,
        seen: &mut HashSet<String>,
    ) -> io::Result<()> {
        for (position, block) in blocks.iter_mut().enumerate() {
            locator.push(u32::try_from(position).map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "guarded projection tree is too wide",
                )
            })?);
            let identity = identities.get(*index).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "guarded projection target has incomplete identity authority",
                )
            })?;
            if identity.locator != *locator
                || identity.block_identity.is_empty()
                || !seen.insert(identity.block_identity.clone())
            {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "guarded projection target identity authority is non-canonical",
                ));
            }
            block.uuid.clone_from(&identity.block_identity);
            *index += 1;
            bind_blocks(&mut block.children, locator, identities, index, seen)?;
            locator.pop();
        }
        Ok(())
    }

    let mut index = 0;
    bind_blocks(
        &mut document.roots,
        &mut Vec::new(),
        identities,
        &mut index,
        &mut HashSet::with_capacity(identities.len()),
    )?;
    if index != identities.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "guarded projection target has excess identity authority",
        ));
    }
    Ok(())
}

#[cfg(test)]
fn canonical_guarded_projection_layout_for_test(
    graph: &Graph,
    relative_path: &str,
    target: &[u8],
) -> io::Result<GuardedProjectionLayout> {
    let target_path = graph.projection_page_target(relative_path)?;
    let target_text = std::str::from_utf8(target).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "test projection target is not valid UTF-8",
        )
    })?;
    Ok(GuardedProjectionLayout::canonical_for_test(&parse_doc(
        &target_path.absolute_path,
        target_text,
    )))
}

/// Lightweight entry for the page list / sidebar.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PageEntry {
    pub name: String,
    pub kind: PageKind,
    /// Sort key `yyyymmdd` for journals; `None` for ordinary pages.
    pub date_key: Option<i64>,
    /// Graph-root-relative path exposed to the frontend so duplicate basenames
    /// can be opened by file, not by ambiguous `(kind,name)`.
    #[serde(rename = "path", default)]
    pub rel_path: String,
    #[serde(skip)]
    pub path: PathBuf,
}

/// Digest of one exact user-visible Markdown/Org source file.
#[derive(Debug, Clone, Eq, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct GraphTextSourceDigest {
    pub path: String,
    pub length: u64,
    pub digest: String,
}

/// One parser-owned interpretation of a present external graph-text document.
///
/// The filename fallback and parser-declared title remain distinct so callers
/// can compare current content authority with an authenticated prior document
/// without conflating either fact with an already accepted oplog identity.
/// Journal conversion is represented only by `effective`: it is applied after
/// selecting the explicit title or filename fallback, matching OG.
pub(crate) struct ParsedExternalDocument {
    pub(crate) format: Format,
    pub(crate) explicit_title: Option<String>,
    pub(crate) filename_fallback: PageEntry,
    pub(crate) effective: PageEntry,
    pub(crate) parsed: doc::ParsedDocument,
    pub(crate) revision: String,
    /// `None` when the caller only needs read-compatible semantics. Import-grade
    /// parsing records whether the source is structurally editable, but a false
    /// result is now an exact read-only source rather than an admission failure.
    pub(crate) source_round_trips: Option<bool>,
}

/// An already accepted exact-path identity that may survive parser-policy
/// changes only while the parser-owned explicit-title evidence is unchanged.
pub(crate) struct AcceptedExternalDocumentIdentity<'a> {
    pub(crate) name: &'a str,
    pub(crate) kind: PageKind,
    pub(crate) explicit_title: Option<&'a str>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct ExternalDocumentIdentity {
    pub(crate) name: String,
    pub(crate) kind: PageKind,
}

impl ParsedExternalDocument {
    /// Apply the one accepted-versus-explicit-versus-filename identity rule
    /// shared by affected import and local editor authoring.
    pub(crate) fn resolve_identity(
        &self,
        accepted: Option<AcceptedExternalDocumentIdentity<'_>>,
    ) -> ExternalDocumentIdentity {
        resolve_external_document_identity(
            self.explicit_title.as_deref(),
            &self.filename_fallback,
            &self.effective,
            accepted,
        )
    }

    /// Consume one already parsed exact managed-text target into the ordinary
    /// application DTO.  This is deliberately the same projection used by
    /// [`Graph::parse_exact_page_dto`], but lets a caller that has already
    /// consumed the parser result for response preparation avoid parsing its
    /// requested target a second time.
    pub(crate) fn into_exact_page_dto(
        self,
        path: &ManagedPath,
        content: &str,
    ) -> io::Result<PageDto> {
        let mut dto = page_dto_checked(&self.effective, &self.parsed.document)?;
        dto.read_only = match self.format {
            Format::Md => !doc::markdown_structurally_round_trips_parsed(content, &self.parsed),
            Format::Org => !crate::org::org_editable_parsed(content, &self.parsed),
        };
        dto.rev = Some(self.revision);
        dto.path = path.as_str().to_owned();
        Ok(dto)
    }
}

pub(crate) fn resolve_external_document_identity(
    explicit_title: Option<&str>,
    filename_fallback: &PageEntry,
    effective: &PageEntry,
    accepted: Option<AcceptedExternalDocumentIdentity<'_>>,
) -> ExternalDocumentIdentity {
    if let Some(accepted) = accepted {
        if explicit_title == accepted.explicit_title {
            return ExternalDocumentIdentity {
                name: accepted.name.to_owned(),
                kind: accepted.kind,
            };
        }
    }
    let selected = if explicit_title.is_some() {
        effective
    } else {
        filename_fallback
    };
    ExternalDocumentIdentity {
        name: selected.name.clone(),
        kind: selected.kind,
    }
}

