    /// Stable identity of the exact no-follow directory capability retained at
    /// graph open. This is the only graph-root identity accepted by sparse
    /// projection enrollment; the ambient path in `Graph::root` is not authority.
    pub fn canonical_resource_id(&self) -> io::Result<CanonicalGraphResourceId> {
        let root = self.projection_root.as_ref().ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::Unsupported,
                "graph has no retained no-follow projection capability",
            )
        })?;
        canonical_graph_resource_id(root)
    }

    pub fn graph_text_scope_version(&self) -> u32 {
        self.graph_text_scope.version()
    }

    /// Snapshot the graph-text discovery policy without granting any write
    /// authority. Launch backups use the same eligibility rules as graph reads.
    pub fn graph_text_scope(&self) -> GraphTextScope {
        self.graph_text_scope.clone()
    }

    /// Bind the precomputed effective graph-text policy to the exact retained
    /// graph-root capability without walking or hashing graph contents.
    pub fn graph_text_scope_binding(&self) -> io::Result<GraphTextScopeBinding> {
        Ok(self
            .graph_text_scope
            .bind_graph_resource(self.canonical_resource_id()?))
    }

    /// Seal this exact Graph instance for a future external-reconciliation
    /// publisher. The workspace and endpoint become immutable evidence on the
    /// capability; this method never exposes the underlying reservation.
    pub(crate) fn mint_handoff_safe(
        &self,
        workspace_id: WorkspaceId,
        endpoint: ProjectionEndpointBinding,
    ) -> io::Result<HandoffSafe> {
        let graph_resource_id = self.canonical_resource_id()?;
        let binding = self.managed_write_binding()?;
        if binding.resource_id != graph_resource_id {
            return Err(managed_write_identity_mismatch_error());
        }
        if endpoint.graph_resource_id() != graph_resource_id {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "external reconciliation endpoint is not bound to this graph resource",
            ));
        }
        binding.gate.reserve_handoff()?;
        if let Err(error) = handoff_mint_after_reservation_hook() {
            binding.gate.release_handoff();
            return Err(error);
        }
        Ok(HandoffSafe {
            gate: Some(Arc::clone(&binding.gate)),
            instance_token: Arc::clone(&self.handoff_instance_token),
            binding: HandoffBindingEvidence {
                workspace_id,
                endpoint,
                graph_resource_id,
            },
        })
    }

    /// Reacquire the process-local latch for an already-authenticated
    /// published continuation. Unlike ordinary minting, a held latch is the
    /// expected same-process crash residue and is adopted rather than treated
    /// as a competing writer. Callers must authenticate the exact immutable
    /// manifest before entering this narrow recovery seam.
    pub(crate) fn reconstruct_published_handoff_safe(
        &self,
        workspace_id: WorkspaceId,
        endpoint: ProjectionEndpointBinding,
    ) -> io::Result<HandoffSafe> {
        let graph_resource_id = self.canonical_resource_id()?;
        let binding = self.managed_write_binding()?;
        if binding.resource_id != graph_resource_id
            || endpoint.graph_resource_id() != graph_resource_id
        {
            return Err(managed_write_identity_mismatch_error());
        }
        let reconstructed = {
            let mut state = binding.gate.state.lock().unwrap();
            if state.active_writers != 0 {
                return Err(handoff_write_blocked_error());
            }
            if state.handoff_held {
                false
            } else {
                state.handoff_held = true;
                #[cfg(test)]
                {
                    state.recovered_handoff_reconstructions += 1;
                }
                true
            }
        };
        if let Err(error) = handoff_mint_after_reservation_hook() {
            if reconstructed {
                binding.gate.release_handoff();
            }
            return Err(error);
        }
        Ok(HandoffSafe {
            gate: Some(Arc::clone(&binding.gate)),
            instance_token: Arc::clone(&self.handoff_instance_token),
            binding: HandoffBindingEvidence {
                workspace_id,
                endpoint,
                graph_resource_id,
            },
        })
    }

    fn admit_managed_text_writer(&self) -> io::Result<ManagedTextWritePermit> {
        // Every graph-text write in this file passes through here, which is why
        // the read-only view is enforced at this one point rather than trusted
        // to each of the ~28 callers.
        if self.derived_read_only {
            return Err(derived_read_only_write_error());
        }
        let binding = self.managed_write_binding()?;
        let mut permit = binding.gate.admit_writer()?;
        if let Err(error) = managed_write_after_admission_hook() {
            drop(permit);
            return Err(error);
        }
        permit.root = Some(binding.root.try_clone()?);
        permit.resource_id = Some(binding.resource_id);
        managed_write_after_identity_check_hook();
        Ok(permit)
    }

